import sys, json, uuid, datetime

# GH #138 (ruling R-0904-6) -- this cell's page bounds are PARAMS, not
# environment. The incoming message and this cell's own configuration arrive on
# the same stdin document: `params` is one of its three top-level objects,
# beside `envelope` and `body`, and the substrate always sets it ({} when there
# is nothing to hand over). So the bound is per-INSTANCE -- two registries in
# one colony page apart, and a mutation retunes one of them without touching a
# colony-wide environment. The literal beside each name is the shipped default,
# and it is the same number `contract.settings` declares.


def _knob(key, default):
    # A knob explicitly set to null or to whitespace is "not configured", not a
    # crash: an operator who blanks a line in a config means the default.
    v = P.get(key, default)
    return default if v is None else v


def _int(key, default):
    v = _knob(key, default)
    if isinstance(v, str) and not v.strip():
        return default
    return int(v)



# The rank, as a literal, because it is part of the contract and not an
# implementation detail: cheapest completion first, cheapest prompt next, more
# context next, and the model id last as the total tie-break. The last key is
# what makes the choice DETERMINISTIC -- two runs over the same catalog cannot
# disagree, because no two active rows share a model_id.
RANK = "cost_out asc, cost_in asc, context_window desc, model_id asc"
ORDER = [{"col": "cost_out", "dir": "asc"}, {"col": "cost_in", "dir": "asc"},
         {"col": "context_window", "dir": "desc"}, {"col": "model_id", "dir": "asc"}]
MODEL_COLS = ["model_id", "provider", "base_url", "wire_dialect", "context_window",
              "cost_in", "cost_out", "caps", "traits", "status", "note"]


def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def emit(route, phase, carry, extra, body=None):
    h = {"route": route, "phase": phase,
         "carry": json.dumps(carry) if carry else "",
         "resolved": "", "reason_code": "", "model_id": "", "tier": ""}
    h.update(extra or {})
    m = {"header": h}
    m.update(body or {})
    return m


def store(operation, phase, carry, **rest):
    args = {"operation": operation}
    args.update(rest)
    return emit("rstore", phase, carry, None, {
        "messages": [{"origin": "assistant", "type": "tool_call",
                      "id": uuid.uuid4().hex[:12], "text": json.dumps(args)}]})


def fail(detail):
    return emit("error", "", None, {}, {
        "messages": [{"origin": "tool", "type": "tool_result", "id": "",
                      "text": "llm-registry/select: " + detail}]})


def rows_of(d):
    """The store's result, as rows: one turn, JSON in its text."""
    msgs = d.get("messages") or []
    if not msgs:
        return []
    try:
        v = json.loads(msgs[-1].get("text") or "null")
    except Exception:
        return []
    return v if isinstance(v, list) else []


def as_obj(v):
    """A `json` column arrives as the TEXT the store kept."""
    if isinstance(v, dict):
        return v
    if isinstance(v, str) and v.strip():
        try:
            p = json.loads(v)
        except Exception:
            return {}
        return p if isinstance(p, dict) else {}
    return {}


def as_int(v, fallback=None):
    try:
        return int(v)
    except Exception:
        return fallback


def rank_key(m):
    return (as_int(m.get("cost_out"), 0), as_int(m.get("cost_in"), 0),
            -as_int(m.get("context_window"), 0), str(m.get("model_id") or ""))


def shortfall(m, req):
    """Why this model does NOT satisfy the request -- "" when it does.

    Every branch is a comparison. There is no scoring, no closeness, no "near
    enough": a requirement is met or the model is out.
    """
    caps = as_obj(m.get("caps"))
    for c in req["caps"]:
        if caps.get(c) is not True:
            return "capability_missing"
    if req["max_cost"] is not None and as_int(m.get("cost_out"), 0) > req["max_cost"]:
        return "over_budget"
    if req["min_context"] is not None \
            and as_int(m.get("context_window"), 0) < req["min_context"]:
        return "context_too_small"
    return ""


def answer(req, resolved, model, reason_code, detail, considered):
    payload = {"resolved": bool(resolved), "tier": req["tier"],
               "reason_code": reason_code, "considered": considered, "rank": RANK}
    if detail:
        payload["detail"] = detail
    if resolved:
        payload["model_id"] = str(model.get("model_id") or "")
        payload["provider"] = str(model.get("provider") or "")
        payload["base_url"] = str(model.get("base_url") or "")
        payload["wire_dialect"] = str(model.get("wire_dialect") or "")
        payload["context_window"] = as_int(model.get("context_window"), 0)
        payload["cost_in"] = as_int(model.get("cost_in"), 0)
        payload["cost_out"] = as_int(model.get("cost_out"), 0)
        payload["caps"] = as_obj(model.get("caps"))
    else:
        # A refusal names no model at all. Not the closest one, not a default:
        # a guess here would be a wrong answer wearing the shape of a right one.
        payload["model_id"] = ""
    return emit("answer", "", None,
                {"resolved": "true" if resolved else "false",
                 "reason_code": reason_code, "tier": req["tier"],
                 "model_id": payload["model_id"]},
                {"messages": [{"origin": "tool", "type": "tool_result",
                               "id": req["call_id"], "text": json.dumps(payload)}]})


def journal(req, model_id, reason_code):
    """Every resolution, granted or refused, leaves one line. A refusal is the
    half of the log worth reading: it says the catalog could not answer."""
    return store("insert", "written", None, table="resolutions", row={
        "id": uuid.uuid4().hex, "tier": req["tier"], "model_id": model_id,
        "cell_path": req["asker"], "at": now(), "reason": reason_code})


doc = json.load(sys.stdin)
d = doc["body"]
P = doc.get("params") or {}
TIER_ROWS = _int("tier_rows", 200)
MODEL_ROWS = _int("model_rows", 500)
envelope = doc["envelope"]
header = envelope.get("header") or {}
hop = header.get("hop") or {}
context = header.get("context") or {}
echo = "operation" in hop
phase = str(context.get("lr_phase") or "") if echo else "in"
try:
    carry = json.loads(str(context.get("lr_carry") or "{}")) or {}
except Exception:
    carry = {}

if echo and str(hop.get("error_code") or ""):
    sys.stdout.write(json.dumps([fail("store rejected op %s (%s)" % (
        hop.get("operation"), hop.get("error_code")))]))
    sys.exit(0)

if phase == "in":
    call_id, raw = "", None
    for m in reversed(d.get("messages") or []):
        if m.get("type") == "tool_call":
            call_id = str(m.get("id") or "")
            try:
                raw = json.loads(str(m.get("text") or "null"))
            except Exception:
                raw = None
            break
    if not isinstance(raw, dict):
        sys.stdout.write(json.dumps([fail("request is not a tool_call turn "
                                          "carrying a JSON object")]))
        sys.exit(0)
    caps = raw.get("capability")
    if isinstance(caps, str):
        caps = [caps]
    if not isinstance(caps, list):
        caps = []
    req = {"tier": str(raw.get("tier") or ""),
           # sorted + de-duplicated, so two spellings of the same request are
           # one request and produce one journal reason.
           "caps": sorted({str(c) for c in caps if str(c).strip()}),
           "max_cost": as_int(raw.get("max_cost")),
           "min_context": as_int(raw.get("min_context")),
           # Edge truth, never body text: who asked is what the edge promoted.
           "asker": str(context.get("asker") or ""),
           "call_id": call_id}
    sys.stdout.write(json.dumps([store(
        "select", "tiers", {"req": req}, table="tiers",
        columns=["tier", "model_id", "since", "active"], where={"active": 1},
        order_by=[{"col": "tier", "dir": "asc"}, {"col": "since", "dir": "desc"}],
        limit=TIER_ROWS)]))
    sys.exit(0)

if phase == "tiers":
    req = carry.get("req") or {}
    tiers = {}
    for r in rows_of(d):
        if isinstance(r, dict) and str(r.get("tier") or "") not in tiers:
            tiers[str(r.get("tier") or "")] = str(r.get("model_id") or "")
    sys.stdout.write(json.dumps([store(
        "select", "models", {"req": req, "tiers": tiers}, table="models",
        columns=MODEL_COLS, where={"status": "active"}, order_by=ORDER,
        limit=MODEL_ROWS)]))
    sys.exit(0)

if phase == "models":
    req = carry.get("req") or {}
    tiers = carry.get("tiers") or {}
    models = {}
    for r in rows_of(d):
        if isinstance(r, dict) and str(r.get("model_id") or ""):
            models[str(r.get("model_id"))] = r
    considered = len(models)

    if req.get("tier"):
        # A named tier is an INDEX LOOKUP, not a search. If the model behind it
        # cannot serve the request, the answer is no -- picking a different one
        # would silently move a cell off the tier its operator chose.
        mid = tiers.get(req["tier"], "")
        if not mid:
            out = [answer(req, False, None, "unknown_tier", "", considered),
                   journal(req, "", "unknown_tier")]
        elif mid not in models:
            out = [answer(req, False, None, "tier_model_inactive", mid, considered),
                   journal(req, "", "tier_model_inactive")]
        else:
            miss = shortfall(models[mid], req)
            if miss:
                out = [answer(req, False, None, "tier_below_requirement", miss,
                              considered),
                       journal(req, "", "tier_below_requirement")]
            else:
                out = [answer(req, True, models[mid], "tier_active", "", considered),
                       journal(req, mid, "tier_active")]
    else:
        cands = sorted([m for m in models.values() if not shortfall(m, req)],
                       key=rank_key)
        if not cands:
            out = [answer(req, False, None, "no_candidate", "", considered),
                   journal(req, "", "no_candidate")]
        else:
            out = [answer(req, True, cands[0], "ranked", "", considered),
                   journal(req, str(cands[0].get("model_id") or ""), "ranked")]
    sys.stdout.write(json.dumps(out))
    sys.exit(0)

# phase "written": the store's echo of the journal line. Nothing follows it.
sys.stdout.write("[]")
